/**
 * Fixed-capacity LRU cache backed by a hash map and an intrusive doubly
 * linked list stored in primitive arrays. Every operation is O(1) expected.
 */
class LruCache<K : Any, V : Any>(private val capacity: Int) {
    init {
        require(capacity >= 1) { "capacity must be positive, was $capacity" }
    }

    private val index = HashMap<K, Int>()
    private val keys = arrayOfNulls<Any>(capacity + 1)
    private val values = arrayOfNulls<Any>(capacity + 1)
    private val prev = IntArray(capacity + 1)
    private val next = IntArray(capacity + 1)
    private val freeSlots = IntArray(capacity + 1)
    private var freeCount = 0
    private var nextSlot = 0
    private var head = NIL // most recently used
    private var tail = NIL // least recently used

    val size: Int get() = index.size

    operator fun get(key: K): V? {
        val slot = index[key] ?: return null
        moveToFront(slot)
        return valueAt(slot)
    }

    operator fun set(key: K, value: V) {
        index[key]?.let { slot ->
            values[slot] = value
            moveToFront(slot)
            return
        }
        val slot = if (freeCount > 0) freeSlots[--freeCount] else nextSlot++
        keys[slot] = key
        values[slot] = value
        index[key] = slot
        pushFront(slot)
        if (index.size > capacity) removeSlot(tail)
    }

    /** Removes [key]; returns whether it was present. */
    fun remove(key: K): Boolean {
        val slot = index[key] ?: return false
        removeSlot(slot)
        return true
    }

    @Suppress("UNCHECKED_CAST")
    private fun valueAt(slot: Int): V = values[slot] as V

    private fun removeSlot(slot: Int) {
        unlink(slot)
        index.remove(keys[slot])
        keys[slot] = null
        values[slot] = null
        freeSlots[freeCount++] = slot
    }

    private fun pushFront(slot: Int) {
        prev[slot] = NIL
        next[slot] = head
        if (head != NIL) prev[head] = slot else tail = slot
        head = slot
    }

    private fun unlink(slot: Int) {
        val p = prev[slot]
        val n = next[slot]
        if (p != NIL) next[p] = n else head = n
        if (n != NIL) prev[n] = p else tail = p
    }

    private fun moveToFront(slot: Int) {
        if (slot == head) return
        unlink(slot)
        pushFront(slot)
    }

    private companion object {
        const val NIL = -1
    }
}

import java.io.BufferedOutputStream
import java.io.PrintStream
import kotlin.system.exitProcess

private fun parseCapacity(line: String?): Int =
    line?.trim()?.takeWhile { it.isDigit() }?.toIntOrNull()?.takeIf { it >= 1 }
        ?: run {
            System.err.println("invalid capacity: ${line ?: "<missing>"}")
            exitProcess(1)
        }

fun main() {
    val input = System.`in`.readBytes().toString(Charsets.ISO_8859_1)
    val lines = input.lineSequence().iterator()
    val cache = LruCache<String, String>(parseCapacity(if (lines.hasNext()) lines.next() else null))
    val out = PrintStream(BufferedOutputStream(System.out, 1 shl 16), false, Charsets.ISO_8859_1)

    for (rawLine in lines) {
        val line = rawLine.removeSuffix("\r")
        if (line.isEmpty()) continue
        val sp1 = line.indexOf(' ')
        val command = if (sp1 < 0) line else line.substring(0, sp1)
        val args = line.substring(sp1 + 1)
        when (command) {
            "SET" -> {
                val sp2 = args.indexOf(' ')
                if (sp2 >= 0) cache[args.substring(0, sp2)] = args.substring(sp2 + 1)
            }
            "GET" -> out.println(cache[args] ?: "NULL")
            "DEL" -> out.println(if (cache.remove(args)) "1" else "0")
            "SIZE" -> out.println(cache.size)
            else -> Unit // ignore unknown commands
        }
    }
    out.flush()
}
